#!/usr/bin/env python3\n\"\"\"Switch between named global Git identities.\"\"\"\n\nimport argparse\nimport json\nimport os\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nCONFIG_PATH = Path(os.environ.get(\"XDG_CONFIG_HOME\", Path.home() / \".config\")) / \"git-swap\" / \"profiles.json\"\n\ndef load_profiles():\n    if not CONFIG_PATH.exists(): return {\"profiles\": {}, \"active\": None}\n    try:\n        data = json.loads(CONFIG_PATH.read_text())\n        return {\"profiles\": data.get(\"profiles\", {}), \"active\": data.get(\"active\")}\n    except (OSError, json.JSONDecodeError) as exc: raise RuntimeError(f\"Could not read {CONFIG_PATH}: {exc}\") from exc\n\ndef save_profiles(data):\n    CONFIG_PATH.parent.mkdir(parents=True, exist_ok=True)\n    CONFIG_PATH.write_text(json.dumps(data, indent=2) + \"\\n\")\n    os.chmod(CONFIG_PATH, 0o600)\n\ndef git_config(key, value=None):\n    command = [\"git\", \"config\", \"--global\", key]\n    if value is not None: command.append(value)\n    result = subprocess.run(command, text=True, capture_output=True)\n    if result.returncode: raise RuntimeError(result.stderr.strip() or \"git config failed\")\n    return result.stdout.strip()\n\ndef add(args):\n    data = load_profiles()\n    if args.profile in data[\"profiles\"] and not args.force: raise RuntimeError(f\"Profile '{args.profile}' already exists; use --force to replace it\")\n    data[\"profiles\"][args.profile] = {\"name\": args.git_name, \"email\": args.email}\n    save_profiles(data); print(f\"Saved profile '{args.profile}'.\")\n\ndef list_profiles(_args):\n    data = load_profiles()\n    if not data[\"profiles\"]:\n        print(\"No profiles yet. Add one with: git-swap add <profile> --name <name> --email <email>\"); return\n    for profile, values in sorted(data[\"profiles\"].items()):\n        marker = \" *\" if profile == data.get(\"active\") else \"\"\n        print(f\"{profile}{marker}\\t{values['name']} <{values['email']}>\")\n\ndef use(args):\n    data = load_profiles(); profile = data[\"profiles\"].get(args.profile)\n    if profile is None: raise RuntimeError(f\"Profile '{args.profile}' does not exist\")\n    git_config(\"user.name\", profile[\"name\"]); git_config(\"user.email\", profile[\"email\"])\n    data[\"active\"] = args.profile; save_profiles(data)\n    print(f\"Switched to '{args.profile}' ({profile['name']} <{profile['email']}>).\")\n\ndef remove(args):\n    data = load_profiles()\n    if args.profile not in data[\"profiles\"]: raise RuntimeError(f\"Profile '{args.profile}' does not exist\")\n    del data[\"profiles\"][args.profile]\n    if data.get(\"active\") == args.profile: data[\"active\"] = None\n    save_profiles(data); print(f\"Removed profile '{args.profile}'.\")\n\ndef current(_args):\n    data = load_profiles(); print(data[\"active\"] if data.get(\"active\") else \"No active git-swap profile.\")\n\ndef build_parser():\n    parser = argparse.ArgumentParser(prog=\"git-swap\", description=\"Switch between Git user profiles.\")\n    commands = parser.add_subparsers(dest=\"command\", required=True)\n    add_parser = commands.add_parser(\"add\", help=\"save a profile\"); add_parser.add_argument(\"profile\"); add_parser.add_argument(\"--name\", dest=\"git_name\", required=True); add_parser.add_argument(\"--email\", required=True); add_parser.add_argument(\"--force\", action=\"store_true\"); add_parser.set_defaults(func=add)\n    commands.add_parser(\"list\", aliases=[\"ls\"], help=\"list profiles\").set_defaults(func=list_profiles)\n    use_parser = commands.add_parser(\"use\", help=\"activate a profile\"); use_parser.add_argument(\"profile\"); use_parser.set_defaults(func=use)\n    commands.add_parser(\"current\", help=\"show the active profile\").set_defaults(func=current)\n    remove_parser = commands.add_parser(\"remove\", aliases=[\"rm\"], help=\"delete a saved profile\"); remove_parser.add_argument(\"profile\"); remove_parser.set_defaults(func=remove)\n    return parser\n\ndef main(argv=None):\n    try:\n        args = build_parser().parse_args(argv); args.func(args); return 0\n    except RuntimeError as exc:\n        print(f\"git-swap: error: {exc}\", file=sys.stderr); return 1\n\nif __name__ == \"__main__\": raise SystemExit(main())\n